// Extract email data and prepare thread ID for fetching
const email = $input.first().json;

return {
  json: {
    emailId: $input.first().json.id,
    threadId: $input.first().json.threadId,
    subject: $input.first().json.subject || '',
    fromEmail: $input.first().json.from.value[0].address,
    fromName: $input.first().json.from.value[0].name,
    toEmail: $input.first().json.to.text,
    date: $input.first().json.date || '',
    bodyPlain: $input.first().json.text || '',
    bodyFull: $input.first().json.textAsHtml || email.snippet || '',
    hasAttachments: email.payload?.parts?.some(p => p.filename) || false,
    labels: $input.first().json.labelIds || [],
    processedTimestamp: new Date().toISOString()
  }
};

// Parse AI classification response
const aiResponse = $input.item.json.message?.content || $input.item.json.text;

let classification;
try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    classification = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (error) {
  classification = {
    category: 'MISCELLANEOUS',
    confidence: 0.5,
    reasoning: 'Failed to parse AI response',
    requiresImmediate: false,
    suggestedResponse: '',
    keyPoints: ['Classification error'],
    escalationLevel: 'none',
    paymentDeadline: null,
    shouldForward: false,
    forwardTo: null,
    autoMarkRead: false
  };
}

const emailData = $('Extract Email Data').first().json;

// Format Gmail label
const gmailLabel = classification.category
    .replace(/_/g, ' ')
    .toLowerCase()
    .replace(/\b\w/g, l => l.toUpperCase());

return {
  json: {
    ...emailData,
    classification: classification.category,
    confidence: classification.confidence,
    reasoning: classification.reasoning,
    requiresImmediate: classification.requiresImmediate || false,
    suggestedResponse: classification.suggestedResponse || '',
    keyPoints: classification.keyPoints || [],
    escalationLevel: classification.escalationLevel || 'none',
    paymentDeadline: classification.paymentDeadline,
    shouldForward: classification.shouldForward || false,
    forwardTo: classification.forwardTo,
    autoMarkRead: classification.autoMarkRead || false,
    gmailLabel: gmailLabel
  }
};

