// Get ALL items from the node (not just first)
  const allItems = $('Get All Labels').all();

  const emailData = $('Parse Classification Result').first().json;

  // Extract json from each item to get array of labels
  const labelsData = allItems.map(item => item.json);

  // Get the label name we want to check
  const targetLabelName = $('Parse Classification Result').first().json.gmailLabel;

  // Debug: vediamo tutti i nomi delle label
  const allLabelNames = labelsData.map(l => l.name);

  // Search for the label
  const existingLabel = labelsData.find(label => label.name === targetLabelName);

  return {
    json: {
      ...$json,
      ...emailData,
      targetLabelName: targetLabelName,  // Cosa stiamo cercando
      allLabelNames: allLabelNames,      // Cosa c'è realmente
      labelId: existingLabel ? existingLabel.id : null,
      labelName: existingLabel ? existingLabel.name : null,
      labelExists: !!existingLabel
    }
  };

