const data = $('Requires Immediate Action').first().json;

  // Componi il messaggio Telegram con condizioni JavaScript
  let message = `🚨 *REQUIRES IMMEDIATE ATTENTION*

  📧 *From:* ${data.fromName} (${data.fromEmail})
  📝 *Subject:* ${data.subject}
  🏷 *Category:* ${data.gmailLabel}`;

  // Aggiungi escalation level solo se non è 'none'
  if (data.escalationLevel && data.escalationLevel !== 'none') {
    message += `\n⚠️ *Escalation Level:* ${data.escalationLevel.toUpperCase()}`;
  }

  // Aggiungi payment deadline solo se esiste
  if (data.paymentDeadline && data.paymentDeadline !== null) {
    message += `\n💰 *Payment Due:* ${data.paymentDeadline}`;
  }

  message += `

  *AI Analysis:*
  ${data.reasoning}

  *Key Points:*`;

  // Aggiungi key points
  if (data.keyPoints && data.keyPoints.length > 0) {
    data.keyPoints.forEach(point => {
      message += `\n• ${point}`;
    });
  } else {
    message += '\n• No key points available';
  }

  message += `

  *📝 SUGGESTED RESPONSE:*
  ${data.suggestedResponse}

  ✅ Draft created in Gmail
  👉 [Open Drafts](https://mail.google.com/mail/u/0/#drafts)
  👉 [View Email](https://mail.google.com/mail/u/0/#inbox/${data.emailId})`;

  return {
    json: {
      ...data,
      telegramMessage: message
    }
  };
